 35→export function StatusBar({
 36→  connected,
 37→  status,
 38→  agentLabel,
 39→  activeModel,
 40→  selectedModel,
 41→  onModelChange,
 42→  showRaw,
 43→  onToggleRaw,
 44→  showTasks,
 45→  onToggleTasks,
 46→  showDiffs,
 47→  onToggleDiffs,
 48→  onToggleSidebar,
 49→  onOpenSfxSettings,
