122→          >
123→            <Menu className="size-4" />
124→          </button>
125→        )}
126→        <span className="text-muted-foreground font-semibold hidden md:inline">thos dashboard</span>
127→        <span className="text-muted-foreground font-semibold md:hidden">thos</span>
128→        {agentLabel && (
129→          <>
130→            <span className="text-muted-foreground/50">/</span>
131→            <Tip text={agentLabel}><span className="truncate max-w-[150px] md:max-w-[250px] font-medium text-foreground/80">{agentLabel}</span></Tip>
132→          </>
133→        )}
134→      </div>
135→
136→      {/* Right side */}
137→      <div className="flex items-center gap-1.5 md:gap-3">
138→        <span className="flex items-center gap-1.5">
139→          <span
140→            className={`inline-block size-2 rounded-full ${
141→              connected ? "bg-green-500" : "bg-red-500"
142→            }`}
143→          />
144→          <span className="hidden md:inline">
145→            {connected ? "ws connected" : "ws disconnected"}
146→          </span>
147→        </span>
148→        <span className="text-muted-foreground hidden md:inline">|</span>
149→        <span className="hidden md:inline">agent: {STATUS_LABELS[status]}</span>
150→        <span className="text-[10px] md:hidden">{STATUS_LABELS[status]}</span>
151→
152→        {/* Model display + selector */}
153→        {onModelChange && (
154→          <>
155→            <span className="text-muted-foreground hidden md:inline">|</span>
156→            <div className="relative" ref={dropdownRef}>
157→              <button
158→                onClick={() => setDropdownOpen((v) => !v)}
159→                className={cn(
160→                  "flex items-center gap-1 rounded px-1.5 py-0.5 font-mono transition-colors",
161→                  "hover:bg-muted/80 text-muted-foreground",
162→                  dropdownOpen && "bg-muted"
163→                )}
164→                title={displayModel ? `Model: ${displayModel}` : "Select model for next spawn"}
165→              >
166→                <span className="max-w-[120px] truncate text-[10px] md:text-xs md:max-w-[180px]">
167→                  {displayModel ? shortModel(displayModel) : "model"}
168→                </span>
169→                <ChevronDown className="size-3 shrink-0" />
170→              </button>
171→
172→              {dropdownOpen && (
173→                <div className="absolute right-0 top-full z-50 mt-1 min-w-[220px] rounded-md border bg-popover p-1 shadow-md">
174→                  {isActive && activeModel && (
175→                    <div className="px-2 py-1.5 text-[10px] text-muted-foreground border-b mb-1">
176→                      Active: <span className="font-mono">{activeModel}</span>
