 33→export function Chat({
 34→  connected,
 35→  loading,
 36→  status,
 37→  agentLabel,
 38→  messages,
 39→  rawMessages,
 40→  activeModel,
 41→  selectedModel,
 42→  onModelChange,
 43→  onSendMessage,
 44→  onSpawnAgent,
 45→  onRespondToControl,
 46→  onRespondToUserQuestion,
 47→  onClearHistory,
 48→  showTasks,
 49→  onToggleTasks,
 50→  showDiffs,
 51→  onToggleDiffs,
 52→  onToggleSidebar,
 53→  onOpenSfxSettings,
 54→}: {
 55→  connected: boolean;
 56→  loading?: boolean;
 57→  status: AgentStatus;
 58→  agentLabel?: string | null;
 59→  messages: ChatMessage[];
 60→  rawMessages: ClaudeMessage[];
 61→  activeModel?: string | null;
 62→  selectedModel?: string;
 63→  onModelChange?: (model: string) => void;
 64→  onSendMessage: (content: string) => void;
