 67→  onRespondToUserQuestion: (requestId: string, answers: Record<string, string>) => void;
 68→  onClearHistory?: () => void;
 69→  showTasks?: boolean;
 70→  onToggleTasks?: () => void;
 71→  showDiffs?: boolean;
 72→  onToggleDiffs?: () => void;
 73→  onToggleSidebar?: () => void;
 74→  onOpenSfxSettings?: () => void;
 75→}) {
 76→  const [input, setInput] = useState("");
 77→  const [showRaw, setShowRaw] = useState(false);
 78→  const [showContext, setShowContext] = useState(false);
