 84→  const inputRef = useRef<HTMLInputElement>(null);
 85→
 86→  const displayItems = useMemo(() => condenseMessages(messages), [messages]);
 87→  const isActive = status === "connected" || status === "thinking";
 88→  const isArchived = status === "done" || status === "disconnected" || status === "error";
 89→
 90→  function handleSubmit(e: React.FormEvent) {
 91→    e.preventDefault();
 92→    const trimmed = input.trim();
 93→    if (!trimmed) return;
 94→
 95→    if (isActive) {
 96→      onSendMessage(trimmed);
 97→    } else {
 98→      onSpawnAgent(trimmed);
 99→    }
100→    setInput("");
101→    setShowSlashMenu(false);
102→  }
103→
104→  function handleInputChange(e: React.ChangeEvent<HTMLInputElement>) {
105→    const value = e.target.value;
106→    setInput(value);
107→
108→    if (value.startsWith("/")) {
109→      setShowSlashMenu(true);
110→      setSlashQuery(value.slice(1));
111→      setSlashHighlight(0);
112→    } else {
113→      setShowSlashMenu(false);
114→      setSlashQuery("");
115→    }
116→  }
117→
118→  function handleKeyDown(e: React.KeyboardEvent<HTMLInputElement>) {
119→    if (!showSlashMenu) return;
120→    const filtered = filterCommands(slashQuery);
121→    if (filtered.length === 0) return;
122→
123→    if (e.key === "ArrowDown") {
124→      e.preventDefault();
125→      setSlashHighlight((i) => (i + 1) % filtered.length);
126→    } else if (e.key === "ArrowUp") {
127→      e.preventDefault();
128→      setSlashHighlight((i) => (i - 1 + filtered.length) % filtered.length);
129→    } else if (e.key === "Enter") {
130→      e.preventDefault();
131→      handleCommandSelect(filtered[slashHighlight]);
132→    } else if (e.key === "Escape") {
133→      e.preventDefault();
134→      setShowSlashMenu(false);
135→    } else if (e.key === "Tab") {
136→      e.preventDefault();
137→      setInput(`/${filtered[slashHighlight].name} `);
138→      setShowSlashMenu(false);
139→    }
140→  }
141→
142→  function handleCommandSelect(command: SlashCommand) {
143→    setShowSlashMenu(false);
144→    setSlashQuery("");
145→    setInput("");
146→
147→    if (command.clientSide) {
148→      if (command.name === "clear") {
149→        onClearHistory?.();
150→      } else if (command.name === "context") {
151→        setShowContext((v) => !v);
152→      }
153→      return;
154→    }
155→
156→    const commandText = `/${command.name}`;
157→    if (isActive) {
158→      onSendMessage(commandText);
159→    } else {
160→      onSpawnAgent(commandText);
161→    }
162→  }
163→
164→  return (
165→    <div className="flex h-full flex-col">
166→      <StatusBar
167→        connected={connected}
168→        status={status}
