172→        onModelChange={onModelChange}
173→        showRaw={showRaw}
174→        onToggleRaw={() => setShowRaw((v) => !v)}
175→        showTasks={showTasks}
176→        onToggleTasks={onToggleTasks}
177→        showDiffs={showDiffs}
178→        onToggleDiffs={onToggleDiffs}
179→        onToggleSidebar={onToggleSidebar}
180→        onOpenSfxSettings={onOpenSfxSettings}
181→      />
182→
183→      <AgentSummary rawMessages={rawMessages} />
184→
185→      <div className="relative flex-1">
186→        {loading ? (
187→          <div className="flex h-full flex-col items-center justify-center gap-3">
188→            <div className="flex gap-1">
189→              <div className="size-2 rounded-full bg-muted-foreground/40 animate-pulse" />
190→              <div className="size-2 rounded-full bg-muted-foreground/40 animate-pulse [animation-delay:150ms]" />
191→              <div className="size-2 rounded-full bg-muted-foreground/40 animate-pulse [animation-delay:300ms]" />
192→            </div>
193→            <span className="text-xs text-muted-foreground">
194→              {connected ? "Loading messages..." : "Connecting..."}
195→            </span>
196→          </div>
197→        ) : showRaw ? (
198→          <div className="h-full overflow-y-auto p-2 md:p-4 space-y-1">
199→            {rawMessages.length === 0 ? (
200→              <div className="flex h-full items-center justify-center text-sm text-muted-foreground">
201→                No raw messages yet
202→              </div>
203→            ) : (
204→              rawMessages.map((msg, i) => (
205→                <RawMessage key={i} message={msg} index={i} />
206→              ))
207→            )}
208→          </div>
209→        ) : (
210→          <Virtuoso
211→            ref={virtuosoRef}
212→            data={displayItems}
213→            style={{ height: "100%" }}
214→            initialTopMostItemIndex={displayItems.length - 1}
215→            followOutput={(isAtBottom) => isAtBottom ? "smooth" : false}
216→            atBottomStateChange={setAtBottom}
217→            increaseViewportBy={200}
218→            itemContent={(_index, item) => (
219→              <div className="px-2 pb-2 md:px-4">
220→                {item.kind === "condensed" ? (
221→                  <CondensedToolGroup key={item.id} group={item} onSendMessage={onSendMessage} />
222→                ) : item.message.userQuestion ? (
223→                  <UserQuestion key={item.message.id} message={item.message} onRespond={onRespondToUserQuestion} />
224→                ) : item.message.controlRequest ? (
225→                  <ControlRequest key={item.message.id} message={item.message} onRespond={onRespondToControl} />
226→                ) : (
227→                  <Message key={item.message.id} message={item.message} onSendMessage={onSendMessage} />
228→                )}
229→              </div>
230→            )}
231→            components={{
232→              Header: () => <div className="h-2" />,
233→              Footer: showContext ? () => (
234→                <div className="px-2 pb-2 md:px-4">
235→                  <div className="flex flex-col gap-0.5 items-start">
236→                    <ContextUsageCard rawMessages={rawMessages} activeModel={activeModel} />
237→                  </div>
238→                </div>
239→              ) : undefined,
240→              EmptyPlaceholder: () => (
241→                <div className="flex h-full flex-col items-center justify-center gap-4 text-muted-foreground">
242→                  <Terminal className="size-10 opacity-30" />
243→                  <div className="text-center">
244→                    <p className="text-sm font-medium text-foreground/80">No agent selected</p>
245→                    <p className="mt-1 text-xs">Type a prompt below to spawn a Claude agent</p>
246→                  </div>
247→                  <div className="mt-2 grid grid-cols-2 gap-3 text-[11px]">
248→                    <div className="flex items-start gap-2 rounded-lg border p-3">
249→                      <MessageSquare className="mt-0.5 size-3.5 shrink-0 text-primary" />
250→                      <div>
251→                        <p className="font-medium text-foreground/80">Chat</p>
252→                        <p className="mt-0.5">Send prompts and review tool calls in real time</p>
253→                      </div>
254→                    </div>
255→                    <div className="flex items-start gap-2 rounded-lg border p-3">
256→                      <ListTodo className="mt-0.5 size-3.5 shrink-0 text-primary" />
257→                      <div>
258→                        <p className="font-medium text-foreground/80">Tasks</p>
259→                        <p className="mt-0.5">Track work with a kanban board and delegate to agents</p>
260→                      </div>
261→                    </div>
262→                  </div>
263→                </div>
264→              ),
265→            }}
266→          />
267→        )}
268→        {!atBottom && displayItems.length > 0 && !showRaw && !loading && (
269→          <button
270→            onClick={() => virtuosoRef.current?.scrollToIndex({ index: displayItems.length - 1, behavior: "smooth" })}
271→            className="absolute bottom-3 right-3 flex items-center gap-1 rounded-full border bg-background/90 px-3 py-1.5 text-xs text-muted-foreground shadow-md backdrop-blur transition-colors hover:text-foreground"
272→          >
273→            <ArrowDown className="size-3" />
274→            Latest
275→          </button>
276→        )}
277→      </div>
278→
279→      {isArchived && messages.length > 0 ? (
280→        <div className="border-t px-4 py-2 text-center text-xs text-muted-foreground">
281→          This session has ended
282→        </div>
283→      ) : (
284→        <form
285→          onSubmit={handleSubmit}
286→          className="relative flex gap-2 border-t px-2 py-2 md:px-4 md:py-3"
287→        >
288→          {showSlashMenu && (
289→            <SlashCommandMenu
290→              query={slashQuery}
291→              highlightedIndex={slashHighlight}
292→              onSelect={handleCommandSelect}
293→              onHighlight={setSlashHighlight}
294→            />
295→          )}
296→          <input
297→            ref={inputRef}
298→            type="text"
299→            value={input}
300→            onChange={handleInputChange}
301→            onKeyDown={handleKeyDown}
302→            placeholder={isActive ? "Send a follow-up..." : "Enter a prompt to spawn agent..."}
303→            className="flex-1 rounded-md border bg-background px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-ring"
304→          />
305→          <Button type="submit" disabled={!connected || !input.trim()}>
306→            {isActive ? "Send" : "Spawn"}
307→          </Button>
308→        </form>
309→      )}
310→    </div>
311→  );
