323→function RawMessage({ message, index }: { message: ClaudeMessage; index: number }) {
324→  const [expanded, setExpanded] = useState(false);
325→  const subtype = (message as { subtype?: string }).subtype;
326→  const typeLabel = subtype ? `${message.type}/${subtype}` : message.type;
