332→        onClick={() => setExpanded((v) => !v)}
333→        className="flex w-full items-center gap-2 rounded px-2 py-1 text-left hover:bg-muted/50 transition-colors"
334→      >
335→        <span className="text-muted-foreground w-6 shrink-0 text-right">{index}</span>
336→        <span className={colorClass}>{typeLabel}</span>
337→        <span className="text-muted-foreground">{expanded ? "▼" : "▶"}</span>
338→      </button>
339→      {expanded && (
340→        <pre className="ml-10 overflow-x-auto rounded bg-muted/30 p-2 text-[10px] text-muted-foreground whitespace-pre-wrap break-all">
341→          {JSON.stringify(message, null, 2)}
342→        </pre>
343→      )}
344→    </div>
345→  );
346→}
