31→}
32→
33→function TooltipContent({
34→  className,
35→  sideOffset = 0,
36→  children,
37→  ...props
38→}: React.ComponentProps<typeof TooltipPrimitive.Content>) {
39→  return (
40→    <TooltipPrimitive.Portal>
