  1→"use client";
  2→
  3→/**
  4→ * Top bar showing the WS connection state (green/red dot), the current
  5→ * agent lifecycle status, active model name, and a model selector dropdown.
  6→ */
  7→
  8→import { useEffect, useRef, useState } from "react";
  9→import { ChevronDown, GitCompareArrows, ListTodo, Menu, Volume2 } from "lucide-react";
 10→import { Button } from "@/components/ui/button";
 11→import { Tip } from "@/components/ui/tip";
 12→import { cn } from "@/lib/utils";
 13→import type { AgentStatus } from "@/lib/types";
 14→
 15→/** Human-readable labels for each agent status. */
 16→const STATUS_LABELS: Record<AgentStatus, string> = {
 17→  idle: "idle",
 18→  spawning: "spawning...",
 19→  connected: "connected",
 20→  thinking: "thinking...",
 21→  done: "done",
 22→  disconnected: "disconnected",
 23→  error: "error",
 24→};
 25→
 26→/** Curated list of common models for the dropdown. */
 27→const MODEL_PRESETS = [
 28→  { value: "", label: "Default (CLI)", description: "Use CLI default model" },
 29→  { value: "claude-sonnet-4-20250514", label: "Sonnet 4", description: "Claude Sonnet 4" },
 30→  { value: "claude-opus-4-20250514", label: "Opus 4", description: "Claude Opus 4" },
 31→  { value: "qwen3-coder", label: "Qwen3 Coder", description: "Ollama — Qwen3 Coder" },
 32→  { value: "devstral", label: "Devstral", description: "Ollama — Devstral" },
 33→];
 34→
 35→export function StatusBar({
 36→  connected,
 37→  status,
 38→  agentLabel,
 39→  activeModel,
 40→  selectedModel,
 41→  onModelChange,
 42→  showRaw,
 43→  onToggleRaw,
 44→  showTasks,
 45→  onToggleTasks,
 46→  showDiffs,
 47→  onToggleDiffs,
 48→  onToggleSidebar,
 49→  onOpenSfxSettings,
 50→}: {
 51→  connected: boolean;
 52→  status: AgentStatus;
 53→  agentLabel?: string | null;
 54→  activeModel?: string | null;
 55→  selectedModel?: string;
 56→  onModelChange?: (model: string) => void;
 57→  showRaw?: boolean;
 58→  onToggleRaw?: () => void;
 59→  showTasks?: boolean;
 60→  onToggleTasks?: () => void;
 61→  showDiffs?: boolean;
 62→  onToggleDiffs?: () => void;
 63→  onToggleSidebar?: () => void;
 64→  onOpenSfxSettings?: () => void;
 65→}) {
 66→  const [dropdownOpen, setDropdownOpen] = useState(false);
 67→  const [customInput, setCustomInput] = useState("");
 68→  const [showCustom, setShowCustom] = useState(false);
 69→  const dropdownRef = useRef<HTMLDivElement>(null);
 70→  const customInputRef = useRef<HTMLInputElement>(null);
 71→
 72→  // Close dropdown on click-outside or Escape
 73→  useEffect(() => {
 74→    if (!dropdownOpen) return;
 75→    function handleClick(e: MouseEvent) {
 76→      if (dropdownRef.current && !dropdownRef.current.contains(e.target as Node)) {
 77→        setDropdownOpen(false);
 78→        setShowCustom(false);
 79→      }
 80→    }
 81→    function handleKey(e: KeyboardEvent) {
 82→      if (e.key === "Escape") {
 83→        setDropdownOpen(false);
 84→        setShowCustom(false);
 85→      }
 86→    }
 87→    document.addEventListener("mousedown", handleClick);
 88→    document.addEventListener("keydown", handleKey);
 89→    return () => {
 90→      document.removeEventListener("mousedown", handleClick);
 91→      document.removeEventListener("keydown", handleKey);
 92→    };
 93→  }, [dropdownOpen]);
 94→
 95→  // Focus custom input when it appears
 96→  useEffect(() => {
 97→    if (showCustom) customInputRef.current?.focus();
 98→  }, [showCustom]);
 99→
100→  /** Shorten a model name for display (e.g. "claude-sonnet-4-20250514" → "sonnet-4"). */
101→  function shortModel(model: string): string {
102→    // Match known preset labels
103→    const preset = MODEL_PRESETS.find((p) => p.value === model);
104→    if (preset && preset.value) return preset.label;
105→    // Strip "claude-" prefix and date suffix for Claude models
106→    const m = model.replace(/^claude-/, "").replace(/-\d{8}$/, "");
107→    return m || model;
108→  }
109→
110→  const displayModel = activeModel ?? (selectedModel || null);
111→  const isActive = status === "connected" || status === "thinking";
112→
113→  return (
114→    <div className="flex items-center justify-between border-b px-2 py-2 text-xs md:px-4">
115→      {/* Left side */}
116→      <div className="flex items-center gap-2">
117→        {onToggleSidebar && (
118→          <button
119→            onClick={onToggleSidebar}
120→            className="rounded p-1 transition-colors hover:bg-muted/50 md:hidden"
121→            aria-label="Toggle sidebar"
122→          >
123→            <Menu className="size-4" />
124→          </button>
125→        )}
126→        <span className="text-muted-foreground font-semibold hidden md:inline">thos dashboard</span>
127→        <span className="text-muted-foreground font-semibold md:hidden">thos</span>
128→        {agentLabel && (
129→          <>
130→            <span className="text-muted-foreground/50">/</span>
131→            <Tip text={agentLabel}><span className="truncate max-w-[150px] md:max-w-[250px] font-medium text-foreground/80">{agentLabel}</span></Tip>
132→          </>
133→        )}
134→      </div>
135→
136→      {/* Right side */}
137→      <div className="flex items-center gap-1.5 md:gap-3">
138→        <span className="flex items-center gap-1.5">
139→          <span
140→            className={`inline-block size-2 rounded-full ${
141→              connected ? "bg-green-500" : "bg-red-500"
142→            }`}
143→          />
144→          <span className="hidden md:inline">
145→            {connected ? "ws connected" : "ws disconnected"}
146→          </span>
147→        </span>
148→        <span className="text-muted-foreground hidden md:inline">|</span>
149→        <span className="hidden md:inline">agent: {STATUS_LABELS[status]}</span>
150→        <span className="text-[10px] md:hidden">{STATUS_LABELS[status]}</span>
151→
152→        {/* Model display + selector */}
