  type: "success" | "error" | "warning" | "info",
  message: string,
  opts: NotifyOptions
) {
  if (opts.isActiveAgent) return;

  const label = opts.agentLabel || opts.agentId.slice(0, 8);
  const toastFn = type === "warning" ? toast.warning : toast[type];

