175→
176→              {dropdownOpen && (
177→                <div className="absolute right-0 top-full z-50 mt-1 min-w-[220px] rounded-md border bg-popover p-1 shadow-md">
178→                  {isActive && activeModel && (
179→                    <div className="px-2 py-1.5 text-[10px] text-muted-foreground border-b mb-1">
180→                      Active: <span className="font-mono">{activeModel}</span>
