186→                  {MODEL_PRESETS.map((preset) => (
187→                    <button
188→                      key={preset.value}
189→                      onClick={() => {
190→                        onModelChange(preset.value);
191→                        setDropdownOpen(false);
192→                        setShowCustom(false);
193→                      }}
