                      className="flex w-full rounded px-2 py-1.5 text-left text-xs text-muted-foreground transition-colors hover:bg-accent"
                    >
                      Custom model...
                    </button>
                  )}
                </div>
              )}
            </div>
          </>
        )}

        <span className="text-muted-foreground hidden md:inline">|</span>
        <div className="flex items-center gap-1.5">
          {onToggleRaw && (
            <button
              onClick={onToggleRaw}
              className={cn(
                "rounded px-2 py-0.5 text-[10px] font-mono transition-colors",
                showRaw
                  ? "bg-foreground text-background"
                  : "bg-muted text-muted-foreground hover:bg-muted/80"
              )}
            >
              {showRaw ? "RAW" : "raw"}
            </button>
          )}
          {onToggleDiffs && (
            <Button
              variant="ghost"
              size="icon-xs"
              onClick={onToggleDiffs}
              title="Toggle diffs"
              className={cn(showDiffs && "text-primary")}
            >
              <GitCompareArrows className="size-3.5" />
            </Button>
          )}
          {onToggleTasks && (
            <Button
              variant="ghost"
              size="icon-xs"
              onClick={onToggleTasks}
              title="Toggle tasks"
              className={cn(showTasks && "text-primary")}
            >
              <ListTodo className="size-3.5" />
            </Button>
          )}
          {onToggleNotifications && (
            <Button
              variant="ghost"
              size="icon-xs"
              onClick={onToggleNotifications}
              title={notificationsEnabled ? "Disable notifications" : "Enable notifications"}
              className={cn(notificationsEnabled && "text-primary")}
            >
              {notificationsEnabled ? <Bell className="size-3.5" /> : <BellOff className="size-3.5" />}
            </Button>
          )}
          {onOpenSfxSettings && (
            <Button
              variant="ghost"
              size="icon-xs"
              onClick={onOpenSfxSettings}
              title="Sound settings"
            >
              <Volume2 className="size-3.5" />
            </Button>
          )}
        </div>
      </div>
    </div>
  );
}

