 40→/** Request browser notification permission. Returns true if granted. */
 41→export async function requestPermission(): Promise<boolean> {
 42→  if (typeof window === "undefined" || !("Notification" in window)) return false;
 43→  if (Notification.permission === "granted") return true;
 44→  if (Notification.permission === "denied") return false;
 45→  const result = await Notification.requestPermission();
 46→  return result === "granted";
 47→}
 48→
 49→// ── Notification options ──────────────────────────────────────────────────
 50→
 51→interface NotifyOptions {
 52→  agentId: string;
 53→  agentLabel: string;
 54→  /** True if this is the currently viewed agent — skips in-app toast. */
 55→  isActiveAgent: boolean;
 56→}
 57→
 58→interface ControlRequestOptions extends NotifyOptions {
 59→  toolName: string;
 60→}
