/** Send a test notification (bypasses document.hidden check). Returns a diagnostic string. */
export function sendTestNotification(): string {
  if (!("Notification" in window)) return "Notification API not available (requires HTTPS or localhost)";
  if (Notification.permission === "denied") return "Permission denied — reset in browser settings";
  if (Notification.permission === "default") return "Permission not yet requested — toggle 'on' first";
  if (Notification.permission !== "granted") return `Unexpected permission state: ${Notification.permission}`;

  try {
    const n = new Notification("thos — test", {
      body: "Desktop notifications are working",
      silent: true,
    });
    n.onclick = () => {
      window.focus();
      n.close();
    };
    return "sent";
  } catch (e) {
    return `Error: ${e instanceof Error ? e.message : String(e)}`;
  }
}

